"""Populate the manuscript exclusively from executed result files."""
from experiment_core import *
from make_figures import labels,classes

def build():
    s=json.loads((R/'analysis/summary.json').read_text());m=s['models'];rob=json.loads((R/'analysis/corruption_summary.json').read_text())['models'];runtime=json.loads((R/'analysis/runtime_summary.json').read_text());th=json.loads((R/'analysis/finite_theory.json').read_text());aug=json.loads((R/'analysis/augmentation_verification.json').read_text());audit=json.loads((R/'analysis/identity_reaudit.json').read_text());ph=json.loads((R/'data/ph2_audit.json').read_text());sr=json.loads((R/'sensitivity/sensitivity_results.json').read_text())
    f=lambda x:f'{x:.3f}';ci=lambda v:f'{v[0]:.3f}–{v[1]:.3f}' if v[0] is not None else 'NE';ms=lambda n,k:f"{m[n]['seed_mean']['C_test'][k]:.3f} ± {m[n]['seed_sd']['C_test'][k]:.3f}";cpm=m['ContrastPenalty'];cp=cpm['datasets']['C_test'];cn=m['ContrastNoPenalty']['datasets']['C_test'];cnn=m['SmallCNN']['datasets']['C_test'];r18=m['ResNet18']['datasets']['C_test'];mob=m['MobileNetV3Small']['datasets']['C_test'];iso=rob['ContrastPenalty']['noise_0.05'];mel=cp['classwise_raw'][4];melci=cp['classwise_ci95'][4];cm=np.array(cp['raw']['confusion']);miss=70-int(cm[4,4]);new={};tables={}
    new['abstract_results']=f"The penalized regional network (3879 parameters) achieved mean macro F1 {ms('ContrastPenalty','macro_f1')} across ten repetitions; its fixed ensemble achieved {f(cp['raw']['macro_f1'])} (lesion-cluster 95% CI {ci(cp['ci95']['macro_f1'])}). The penalty-free graph ensemble achieved {f(cn['raw']['macro_f1'])}; the paired macro F1 difference interval was {ci(s['paired_C_test']['ContrastNoPenalty']['macro_f1'])}. At Gaussian noise σ = 0.05, factorial macro F1 was {f(iso['conditions']['B']['macro_f1'])} for corrupted graphs alone, {f(iso['conditions']['C']['macro_f1'])} for corrupted nodes alone and {f(iso['conditions']['D']['macro_f1'])} for both. Internal argmax melanoma sensitivity was {f(mel['sensitivity'])}; PH2 melanoma AUC was {f(cpm['datasets']['PH2']['raw']['auc'])}."
    new['overlap_results']=f"the largest PH2-to-C normalized cross-correlation was {ph['maximum_cross_dataset_NCC']:.3f}. This is a screening statistic without a validated identity threshold"
    part=audit['development_partitions'];new['partition_results']='Across repetitions, image counts ranged from '+', '.join(f"{min(v[k]['n'] for v in part.values())} to {max(v[k]['n'] for v in part.values())} for {name}" for k,name in [('train','training'),('tune','tuning'),('cal','calibration')])
    new['internal_results_text']=f"The penalized graph's mean macro F1 was {ms('ContrastPenalty','macro_f1')}, compared with {ms('ContrastNoPenalty','macro_f1')} for its penalty-free control and {ms('NoGraph','macro_f1')} for the graph-free encoder. Corresponding fixed-ensemble macro F1 values were {f(cp['raw']['macro_f1'])}, {f(cn['raw']['macro_f1'])} and {f(m['NoGraph']['datasets']['C_test']['raw']['macro_f1'])}. The paired penalized-minus-penalty-free macro F1 interval was {ci(s['paired_C_test']['ContrastNoPenalty']['macro_f1'])}; against graph-free it was {ci(s['paired_C_test']['NoGraph']['macro_f1'])}. These are conditional exploratory intervals. The larger image references achieved mean macro F1 {ms('ResNet18','macro_f1')} for ResNet-18 and {ms('MobileNetV3Small','macro_f1')} for MobileNetV3 Small."
    new['component_results_text']='Fixed-ensemble macro F1 was '+', '.join(f"{f(m[n]['datasets']['C_test']['raw']['macro_f1'])} for {labels[n].lower()}" for n in ['GridOnly','KNNOnly','UniformTopology','RGBOnly','RGBOnlyGraph'])
    new['augmentation_results_text']='Geometric augmentation changed mean macro F1 by '+', '.join(f"{m[n]['seed_mean']['C_test']['macro_f1']-m[n+'_NoAug']['seed_mean']['C_test']['macro_f1']:+.3f} for {labels[n].lower()}" for n in ['NoGraph','ContrastNoPenalty','ContrastPenalty','SmallCNN'])+'. These matched changes characterize this augmentation recipe, rather than a guarantee of robustness. The corruption comparison retains both versions with identical image perturbations.'
    new['classwise_results_text']=f"The penalized ensemble correctly assigned {cm[4,4]} of 70 melanoma images to MEL and assigned {miss} to another class. Its melanoma sensitivity was {f(mel['sensitivity'])} (95% CI {ci(melci['sensitivity'])}) and specificity {f(mel['specificity'])} (95% CI {ci(melci['specificity'])}). Melanoma average precision was {f(mel['average_precision'])}. The DF and VASC intervals are conditional on only eight and 17 test images; their apparent specificity must not obscure unstable sensitivity and precision. All classwise results for the comparators accompany the prediction outputs."
    referral=cp['mel95'];new['referral_results_text']=f"The pooled calibration-derived MEL threshold was {cpm['pooled_calibration_thresholds']['mel95']:.4f}. Transferred unchanged to the C ensemble, it yielded sensitivity {f(referral['sensitivity'])}, specificity {f(referral['specificity'])}, {referral['fn']} false negatives and {referral['fp']} false positives. Targeting 95% on repeated single-model calibration predictions does not ensure 95% sensitivity of an averaged ensemble or of an external cohort. A threshold-triggered referral is an exploratory operating point, not a screened or clinically optimized rule."
    new['isolation_results_text']=f"For σ = 0.05, the clean penalized ensemble had macro F1 {f(iso['conditions']['A']['macro_f1'])}. Across five realizations, replacing only its graph yielded {f(iso['conditions']['B']['macro_f1'])}, replacing only its node descriptors yielded {f(iso['conditions']['C']['macro_f1'])}, and replacing both yielded {f(iso['conditions']['D']['macro_f1'])}. The paired B−A, C−A and D−A intervals were respectively {ci(iso['paired_change_ci95']['B']['macro_f1'])}, {ci(iso['paired_change_ci95']['C']['macro_f1'])} and {ci(iso['paired_change_ci95']['D']['macro_f1'])}. The measured substitutions identify their contributions for the executed perturbation, with an interaction possible when both change."
    structure=iso['structure'];new['topology_results_text']=f"At σ = 0.05, the mean spectral graph distance on the 64-image diagnostic subset was {f(structure['spectral_delta_mean'])}; full-test candidate-edge Jaccard similarity was {f(structure['candidate_jaccard_mean'])}. The average relative change in encoded features was {f(structure['encoded_feature_relative_mean'])}, with a standardized-descriptor change of {f(structure['standardized_descriptor_relative_mean'])}. These different quantities are reported separately, not compared as if they had identical scales. The maximum observed conditional logit-bound ratio across the tested checkpoints and subset was {f(structure['conditional_logit_bound_ratio_max'])}."
    new['robustness_results_text']='At σ = 0.05, mean intact-ensemble macro F1 across five noise realizations was '+', '.join(f"{f(rob[n]['noise_0.05']['conditions']['D']['macro_f1'])} (95% CI {ci(rob[n]['noise_0.05']['conditions']['D']['ci95']['macro_f1'])}) for {labels[n].lower()}" for n in ['ContrastPenalty','RGBOnlyGraph','SmallCNN','ResNet18','MobileNetV3Small'])+'. Detailed macro F1, balanced accuracy and macro average precision under every corruption and component control are supplied in S1. Intervals condition on the fitted ensemble; noise intervals additionally resample the five generated realizations. Blur, JPEG and photometric shifts test distinct perturbations and do not simulate the complete smartphone acquisition process.'
    new['calibration_results_text']=f"Separate temperatures changed penalized-ensemble top-label ECE from {f(cp['raw']['ece'])} to {f(cp['calibrated']['ece'])}; its calibrated ECE interval was {ci(s['calibration_uncertainty']['ContrastPenalty']['top_label_ece_ci95'])}. Its calibrated NLL and Brier score were {f(cp['calibrated']['nll'])} and {f(cp['calibrated']['brier'])}. Classwise MEL binary ECE was {f(cp['classwise_calibrated'][4]['binary_ece'])}, with interval {ci(s['calibration_uncertainty']['ContrastPenalty']['class_binary_ece_ci95'][4])}. Low classwise ECE can be dominated by negative images, and does not replace sensitivity or ranking evidence."
    sel=cp['selective'];new['selective_results_text']=f"The fixed calibration confidence threshold accepted {sel['n_accepted']} of 1227 C images (coverage {f(sel['coverage'])}), with accepted-case accuracy {f(sel['accuracy'])}. It rejected {sel['mel_rejected']} of 70 melanoma images. This selection pattern cannot be interpreted as improved melanoma diagnosis; a refused image would require a separately validated human workflow. Pooled single-model calibration and averaged-ensemble confidence have different distributions, so the target calibration coverage is not guaranteed after averaging."
    ce=cpm['datasets']['E_test'];phm=cpm['datasets']['PH2'];new['external_results_text']=f"Without refitting, the penalized ensemble's E macro F1 was {f(ce['raw']['macro_f1'])} (image-resampled 95% CI {ci(ce['ci95']['macro_f1'])}), with balanced accuracy {f(ce['raw']['balanced_accuracy'])}. On PH2 its unmodified MEL probability gave AUC {f(phm['raw']['auc'])} (95% CI {ci(phm['ci95']['auc'])}); seven-class argmax gave binary sensitivity {f(phm['raw']['sensitivity'])} and specificity {f(phm['raw']['specificity'])}. The transferred calibration threshold instead gave sensitivity {f(phm['mel95']['sensitivity'])} and specificity {f(phm['mel95']['specificity'])}. These are distinct operational rules. The PH2 results use no source images in the distributed archive and no test-based temperature or threshold."
    sensitivity=[];details=[]
    for param,values in CFG['sensitivity_ranges'].items():
        means=[]
        for value in values:
            rows=[r for r in sr if (r['parameter']==param and r['value']==value) or (value==DEFAULT[param] and r['parameter']=='default')];assert len(rows)==3;means.append(np.mean([r['tuning_macro_f1'] for r in rows]));details.append([param,str(value),f"{np.mean([r['tuning_macro_f1'] for r in rows]):.3f} ± {np.std([r['tuning_macro_f1'] for r in rows],ddof=1):.3f}",f(np.mean([r['tuning_metrics']['balanced_accuracy'] for r in rows])),f(np.mean([r['graph_spectral_delta_mean'] for r in rows]))])
        display={'k':'neighbor count k','K':'depth K','alpha':'restart α','sigma_color':'color scale σc','sigma_position':'spatial scale σs','beta':'penalty β'}
        for row in details:
            if row[0]==param:row[0]=display[param]
        sensitivity.append(f"{display[param]}: {min(means):.3f}–{max(means):.3f}")
    new['sensitivity_results_text']='The 42 development fits gave ranges of mean tuning macro F1 across the prespecified values of '+', '.join(sensitivity)+'. The accompanying table retains every evaluated value, balanced accuracy and graph spectral distance. These are selected-checkpoint tuning results and should not be read as unbiased test gains or evidence that the reference parameters are optimal.'
    ver=th['summary'];new['theory_results_text']=f"For 64 training-image graphs and independent random node vectors, the largest recurrence-versus-polynomial difference was {ver['polynomial_error']:.2e} and the spectral reconstruction difference {ver['spectral_error']:.2e}. The largest finite graph-bound, joint-bound and pooling-bound ratios were {ver['finite_graph_bound_ratio']:.4f}, {ver['joint_bound_ratio']:.4f} and {ver['pooling_lipschitz_ratio']:.4f}. The maximum computed graph norm was {ver['operator_norm']:.9f}, within single-precision rounding of one. The four-step coefficient was 2.3616. The descriptor augmentation check compared all eight transformations on 32 images; its maximum descriptor difference was {aug['max_descriptor_equivalence_error']:.2e}. Trained-classifier logit inequalities were additionally checked during the factorial experiments."
    rc={r['name']:r for r in runtime};new['runtime_results_text']=f"On {runtime[0]['processor']}, with four PyTorch threads, the penalized regional model's median batch-one total was {rc['ContrastPenalty']['median_ms']['total']:.2f} ms; preparation accounted for {rc['ContrastPenalty']['median_ms']['preparation']:.2f} ms and forward inference for {rc['ContrastPenalty']['median_ms']['forward']:.2f} ms. The small CNN and ResNet-18 totals were {rc['SmallCNN']['median_ms']['total']:.2f} and {rc['ResNet18']['median_ms']['total']:.2f} ms. These timings are for one checkpoint, not a ten-model ensemble. Inputs are encoded native 28-by-28 PNGs; disk I/O and high-resolution resizing are excluded. Peak process memory includes imported libraries and the loaded benchmark, so it is not model-activation memory or a direct device-memory requirement. No concurrent fitting job ran during the timed measurements."
    new['discussion_results_text']=f"The direct penalized-versus-penalty-free comparison gave ensemble macro F1 {f(cp['raw']['macro_f1'])} versus {f(cn['raw']['macro_f1'])}, with paired interval {ci(s['paired_C_test']['ContrastNoPenalty']['macro_f1'])}. We therefore interpret the penalty through the full set of controlled metrics and failure tests, rather than promoting its design motivation as an established improvement. The factorial evidence at moderate noise separates changes in encoded descriptors from reconstructed graph weights. Removing the six difference coordinates changed the intact corruption result to {f(rob['RGBOnlyGraph']['noise_0.05']['conditions']['D']['macro_f1'])}; this does not prove that every remaining descriptor is clinically adequate. No new boundary annotation or boundary-segmentation accuracy is asserted. On PH2, the penalized regional model's AUC point estimate was close to chance, despite its useful internal ranking scores. This external failure further limits any diagnostic claim."
    new['conclusion_results_text']=f"A finite-step perturbation coefficient of 2.3616 directly characterizes the implemented restart operator. Under ten grouped development repetitions and separate calibration, the 3879-parameter penalized network achieved internal ensemble macro F1 {f(cp['raw']['macro_f1'])}; its PH2 melanoma AUC was {f(phm['raw']['auc'])}. Component substitutions and expanded corruption tests show why those values cannot be inferred from operator stability alone."
    d=np.load(OLD/'data/dermamnist_corrected_28.npz');e=np.load(R/'data/dermamnist_extended_28.npz');dev=np.bincount(np.r_[d['train_labels'].ravel(),d['val_labels'].ravel()],minlength=7);ct=np.bincount(d['test_labels'].ravel(),minlength=7);et=np.bincount(e['test_labels'].ravel(),minlength=7)
    tables['cohorts']=('Cohort class counts (images, not patients). PH2 is evaluated separately as MEL versus all nevi.',['Class','C development','C test','E test','PH2'],[[classes[i],str(dev[i]),str(ct[i]),str(et[i]),'40' if i==4 else '160 nevi' if i==5 else '—'] for i in range(7)]+[['Total','8788','1227','1511','200']],[1.1,1.5,1.1,1.1,1.8])
    names=CFG['central_models'][:7]+['RGBOnlyGraph']+CFG['central_models'][7:]
    desc={'NoGraph':'No propagation','GridOnly':'Grid; weighted','KNNOnly':'Color kNN; weighted','UniformTopology':'Full; constant weights','ContrastNoPenalty':'Full; weighted, beta = 0','ContrastPenalty':'Full; weighted, beta = 1.5','RGBOnly':'Graph-free; six difference features disabled','RGBOnlyGraph':'Full penalized graph; six difference features disabled','SmallCNN':'3 convolutional blocks; mean/max head','ResNet18':'Standard torchvision; from scratch','MobileNetV3Small':'Standard torchvision; from scratch'}
    tables['architectures']=('Matched architectures; each has ten fits. Four additional no-augmentation controls use the same architectures.',['Architecture','Controlled design','Parameters'],[[labels[n],desc[n],f"{m[n]['parameters']:,}"] for n in names],[1.8,3.8,1.0])
    tables['internal_results']=('Internal C test: single-fit mean ± sample SD; fixed-ensemble macro F1 and its conditional lesion-cluster 95% CI. All probabilities are raw.',['Model','Mean F1','Mean BA','Mean AP','Ensemble F1','95% CI'],[[labels[n],ms(n,'macro_f1'),ms(n,'balanced_accuracy'),ms(n,'macro_ap'),f(m[n]['datasets']['C_test']['raw']['macro_f1']),ci(m[n]['datasets']['C_test']['ci95']['macro_f1'])] for n in names],[1.55,1.05,1.05,1.05,.75,1.15])
    tables['augmentation_results']=('Matched geometric augmentation comparison; all architectures retain ten fits for each recipe.',['Architecture','No augmentation F1','Augmentation F1','Mean paired change'],[[labels[n],ms(n+'_NoAug','macro_f1'),ms(n,'macro_f1'),f"{m[n]['seed_mean']['C_test']['macro_f1']-m[n+'_NoAug']['seed_mean']['C_test']['macro_f1']:+.3f}"] for n in ['NoGraph','ContrastNoPenalty','ContrastPenalty','SmallCNN']],[1.9,1.55,1.55,1.6])
    tables['classwise_results']=('Penalized graph ensemble on C. Each value is followed by its lesion-cluster 95% interval; AP is one-versus-rest.',['Class (n)','Sensitivity [CI]','Specificity [CI]','Precision [CI]','F1 [CI]','AP'],[[f"{classes[i]} ({r['n']})"]+[f"{r[k]:.3f}\n[{ci(cp['classwise_ci95'][i][k])}]" for k in ['sensitivity','specificity','precision','f1']]+[f(r['average_precision'])] for i,r in enumerate(cp['classwise_raw'])],[.8,1.25,1.25,1.25,1.25,.8])
    rows=[]
    for n in ['ContrastPenalty','ContrastNoPenalty']:
        rr=rob[n]['noise_0.05']
        for cond in ['A','B','C','D']:
            v=rr['conditions'][cond];rows.append([labels[n],cond,f(v['macro_f1']),ci(v['ci95']['macro_f1']),f(v['balanced_accuracy']),'Reference' if cond=='A' else ci(rr['paired_change_ci95'][cond]['macro_f1'])])
    tables['isolation_results']=('Moderate Gaussian noise (σ = 0.05): five realizations; frozen weights. A = clean; B = graph only; C = nodes only; D = both.',['Model','Case','Macro F1','95% CI','BA','ΔF1 vs A: CI'],rows,[1.55,.4,.75,1.2,.6,2.2])
    show=['ContrastPenalty','ContrastNoPenalty','SmallCNN','ResNet18','MobileNetV3Small']
    tables['calibration_results']=('C test calibration of the ten-network probability ensembles. ECE interval is conditional and lesion-resampled.',['Model','Raw ECE','Cal ECE [CI]','Cal NLL','Cal Brier','MEL ECE','NV ECE'],[[labels[n],f(m[n]['datasets']['C_test']['raw']['ece']),f"{m[n]['datasets']['C_test']['calibrated']['ece']:.3f}\n[{ci(s['calibration_uncertainty'][n]['top_label_ece_ci95'])}]",f(m[n]['datasets']['C_test']['calibrated']['nll']),f(m[n]['datasets']['C_test']['calibrated']['brier']),f(m[n]['datasets']['C_test']['classwise_calibrated'][4]['binary_ece']),f(m[n]['datasets']['C_test']['classwise_calibrated'][5]['binary_ece'])] for n in show],[1.45,.7,1.45,.75,.75,.75,.75])
    tables['external_results']=('DermaMNIST-E seven-class test and source-external PH2 binary melanoma test. AUC uses the unmodified MEL probability; sensitivity/specificity use the original seven-class argmax. Intervals are image-resampled.',['Model','E macro F1 [CI]','E BA','PH2 AUC [CI]','PH2 sens.','PH2 spec.'],[[labels[n],f"{m[n]['datasets']['E_test']['raw']['macro_f1']:.3f}\n[{ci(m[n]['datasets']['E_test']['ci95']['macro_f1'])}]",f(m[n]['datasets']['E_test']['raw']['balanced_accuracy']),f"{m[n]['datasets']['PH2']['raw']['auc']:.3f}\n[{ci(m[n]['datasets']['PH2']['ci95']['auc'])}]",f(m[n]['datasets']['PH2']['raw']['sensitivity']),f(m[n]['datasets']['PH2']['raw']['specificity'])] for n in show],[1.55,1.3,.7,1.45,.8,.8])
    tables['runtime_results']=('Fresh-process CPU benchmark of one checkpoint, native PNG decode → preparation → forward. Peak MiB is total process working set, not isolated model memory.',['Architecture','Decode ms','Prep ms','Forward ms','Total ms','P95 total','Peak MiB'],[[labels[r['name']]]+[f"{r['median_ms'][k]:.2f}" for k in ['decode','preparation','forward','total']]+[f"{r['p95_ms']['total']:.2f}",f"{r['peak_process_MiB']:.1f}"] for r in runtime],[1.7,.65,.75,.8,.8,.9,1.0])
    tables['sensitivity_details']=('Development-only sensitivity: three repetitions per displayed configuration; shared default fits reused for each relevant parameter.',['Parameter','Value','Tuning F1: mean ± SD','Mean BA','Mean spectral ΔS'],details,[1.3,.7,1.9,1.1,1.6])
    dem=[];allmeta=list(csv.DictReader((OLD/'data/DermaMNIST-C.csv').open()))
    for name,ss in [('C development',['train','val']),('C test',['test'])]:
        rows=[v for v in allmeta if v['split'] in ss];age=np.array([float(v['age']) for v in rows if v['age'] not in ['', 'nan']]);sex=[v['sex'] for v in rows];q=np.quantile(age,[.25,.5,.75]);dem.append([name,len(rows),f"{q[1]:.1f} [{q[0]:.1f}–{q[2]:.1f}]",len(rows)-len(age),sex.count('female'),sex.count('male'),len(rows)-sex.count('female')-sex.count('male')])
    tables['demographics']=('Available C demographic metadata (image records, not distinct patients). Age median [IQR], years. E/PH2 individual demographic fields are unavailable here.',['Cohort','Images','Age [IQR]','Age missing','Female','Male','Other/unknown'],dem,[1.3,.7,1.4,.8,.7,.7,1.0])
    tr=json.loads((R/'analysis/transfer_reference.json').read_text());td=tr['datasets'];new['transfer_results_text']=f"The additional reference used {tr['fixed_backbone_parameters']:,} fixed backbone parameters plus 4039 learned head parameters. Internal mean macro F1 was {td['C_test']['seed_mean']['macro_f1']:.3f} ± {td['C_test']['seed_sd']['macro_f1']:.3f}; the fixed ensemble achieved {td['C_test']['raw']['macro_f1']:.3f} (95% CI {ci(td['C_test']['ci95']['macro_f1'])}). On PH2, MEL AUC was {td['PH2']['raw']['auc']:.3f} (95% CI {ci(td['PH2']['ci95']['auc'])}), while the argmax rule missed {td['PH2']['raw']['fn']} of 40 melanomas. At noise σ = 0.05, intact macro F1 was {tr['corruption_mean']['noise_0.05']['macro_f1']:.3f} (95% CI {ci(tr['corruption_mean']['noise_0.05']['macro_f1_ci95'])}). The frozen reference improves upon the failed scratch MobileNet classification, but its pretraining does not ensure noise robustness or clinical safety."
    tables['transfer_reference']=('Additional frozen ImageNet reference, ten independently fitted linear heads. Internal/E intervals use lesion/image units respectively; PH2 reports binary decisions.',['Test cohort','Metric','Ensemble estimate [CI]','Argmax MEL sensitivity','Argmax MEL specificity'],[['C (1227)','Macro F1',f"{td['C_test']['raw']['macro_f1']:.3f} [{ci(td['C_test']['ci95']['macro_f1'])}]",f(td['C_test']['raw']['mel_sensitivity']),f(td['C_test']['raw']['mel_specificity'])],['E (1511)','Macro F1',f"{td['E_test']['raw']['macro_f1']:.3f} [{ci(td['E_test']['ci95']['macro_f1'])}]",f(td['E_test']['raw']['mel_sensitivity']),f(td['E_test']['raw']['mel_specificity'])],['PH2 (200)','MEL ROC AUC',f"{td['PH2']['raw']['auc']:.3f} [{ci(td['PH2']['ci95']['auc'])}]",f(td['PH2']['raw']['sensitivity']),f(td['PH2']['raw']['specificity'])]],[1.0,1.2,1.9,1.25,1.25])
    new['runtime_results_text']=new['runtime_results_text'].replace('disk I/O and high-resolution resizing are excluded.','source clinical-image downsampling and disk I/O are excluded. The frozen ImageNet reference includes its resize, crop and normalization in preparation and its backbone in forward timing.')
    (R/'analysis/manuscript_values.json').write_text(json.dumps({'replacements':new,'tables':tables},indent=2));return new,tables
if __name__=='__main__':build()
